SELECT ?sensor ?ts ?name WHERE {
  ?sensor a brick:ElectricPowerSensor ; brick:pointLocations ?z .
  ?z rdfs:label ?name .
  FILTER(?name = "Perimeter_mid_ZN_4")
  ?sensor ref:hasTimeseriesId ?ts .
}

SELECT ?sensor ?ts WHERE {
  ?sensor brick:pointLocations ?z .
  ?z a brick:Zone ; rdfs:label "Perimeter_mid_ZN_4" .
  ?sensor ref:hasTimeseriesId ?ts .
  FILTER(?sensor a brick:ElectricPowerSensor)
}

SELECT ?sensor ?pclass ?ts WHERE {
  ?sensor brick:pointLocations ?z .
  ?z a brick:Zone ; rdfs:label "Perimeter_mid_ZN_4" .
  ?sensor a ?pclass .
  OPTIONAL { ?sensor ref:hasTimeseriesId ?ts }
}

SELECT ?p ?pclass ?ts WHERE {
  ?z a brick:Zone ; rdfs:label "Perimeter_mid_ZN_4" .
  ?p ?pred ?z .
  ?p a ?pclass .
  OPTIONAL { ?p ref:hasTimeseriesId ?ts }
}

